create table if not exists catalog.store_price_rules (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null unique,
  name text not null,
  calculation_type text not null default 'markup'
    check (calculation_type in ('markup')),
  list_markup_ratio numeric not null
    check (list_markup_ratio >= 0),
  floor_markup_ratio numeric not null
    check (floor_markup_ratio >= 0),
  status text not null default 'active'
    check (status in ('active', 'inactive')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_store_price_rules_tenant_id
  on catalog.store_price_rules (tenant_id);

alter table catalog.product_unit_price_bands
  add column if not exists store_price_rule_id uuid null
    references catalog.store_price_rules (id) on delete set null;

alter table catalog.product_unit_price_bands
  add column if not exists source_type text not null default 'manual'
    check (source_type in ('ruleBased', 'manual'));

alter table catalog.product_unit_price_bands
  add column if not exists is_custom_override boolean not null default false;

create or replace function catalog._compute_suggested_prices(
  p_base_price numeric,
  p_list_markup_ratio numeric,
  p_floor_markup_ratio numeric
)
returns table (
  suggested_list_price numeric,
  suggested_floor_price numeric
)
language plpgsql
immutable
as $$
declare
  v_list numeric;
  v_floor numeric;
begin
  v_list := round(p_base_price * (1 + p_list_markup_ratio));
  v_floor := round(p_base_price * (1 + p_floor_markup_ratio));
  if v_floor > v_list then
    raise exception 'floor_price_greater_than_list_price';
  end if;
  return query select v_list, v_floor;
end;
$$;

create or replace function catalog._resolve_base_product_unit_id(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid default null
)
returns uuid
language plpgsql
stable
security definer
set search_path = catalog, pg_temp
as $$
declare
  v_unit_id uuid;
begin
  v_unit_id := p_product_unit_id;
  if v_unit_id is null then
    select pu.id into v_unit_id
    from catalog.product_units pu
    where pu.product_id = p_product_id
      and pu.tenant_id = p_tenant_id
      and pu.is_base_unit = true
    limit 1;
  end if;
  return v_unit_id;
end;
$$;

