create or replace function catalog.set_store_price_rule(
  p_tenant_id uuid,
  p_name text,
  p_list_markup_ratio numeric,
  p_floor_markup_ratio numeric,
  p_status text default 'active'
)
returns table (
  id uuid,
  tenant_id uuid,
  name text,
  status text,
  calculation_type text,
  list_markup_ratio numeric,
  floor_markup_ratio numeric,
  updated_at timestamptz
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_rule_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.pricing.manage_store_rule') then
    raise exception 'permission denied: catalog.pricing.manage_store_rule';
  end if;

  if p_name is null or btrim(p_name) = '' then
    raise exception 'validation_exception: rule name is required';
  end if;

  if p_list_markup_ratio is null or p_list_markup_ratio < 0
     or p_floor_markup_ratio is null or p_floor_markup_ratio < 0 then
    raise exception 'validation_exception: markup ratios must be non-negative';
  end if;

  if p_status not in ('active', 'inactive') then
    raise exception 'validation_exception: invalid rule status';
  end if;

  perform 1 from catalog._compute_suggested_prices(100, p_list_markup_ratio, p_floor_markup_ratio);

  insert into catalog.store_price_rules (
    tenant_id,
    name,
    calculation_type,
    list_markup_ratio,
    floor_markup_ratio,
    status,
    updated_at
  )
  values (
    p_tenant_id,
    btrim(p_name),
    'markup',
    p_list_markup_ratio,
    p_floor_markup_ratio,
    p_status,
    now()
  )
  on conflict (tenant_id) do update set
    name = excluded.name,
    list_markup_ratio = excluded.list_markup_ratio,
    floor_markup_ratio = excluded.floor_markup_ratio,
    status = excluded.status,
    updated_at = now()
  returning store_price_rules.id into v_rule_id;

  return query
  select
    r.id,
    r.tenant_id,
    r.name,
    r.status,
    r.calculation_type,
    r.list_markup_ratio,
    r.floor_markup_ratio,
    r.updated_at
  from catalog.store_price_rules r
  where r.id = v_rule_id;
end;
$$;

create or replace function catalog.suggest_product_unit_price(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid default null
)
returns table (
  product_id uuid,
  product_unit_id uuid,
  unit_name text,
  base_price numeric,
  currency text,
  suggested_list_price numeric,
  suggested_floor_price numeric,
  store_price_rule_id uuid,
  store_price_rule_name text,
  base_price_version bigint,
  can_suggest boolean,
  unavailable_reason text
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_unit_id uuid;
  v_unit_name text;
  v_base_price numeric;
  v_currency text;
  v_base_price_version bigint;
  v_rule catalog.store_price_rules%rowtype;
  v_prices record;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_pricing') then
    raise exception 'permission denied: catalog.product.manage_pricing';
  end if;

  if not exists (
    select 1 from catalog.products
    where id = p_product_id and tenant_id = p_tenant_id and deleted_at is null
  ) then
    raise exception 'product not found';
  end if;

  v_unit_id := catalog._resolve_base_product_unit_id(p_tenant_id, p_product_id, p_product_unit_id);
  if v_unit_id is null then
    raise exception 'missing base unit';
  end if;

  select u.unit_name into v_unit_name
  from catalog.product_units u
  where u.id = v_unit_id;

  select bp.base_price_amount, bp.currency,
         floor(extract(epoch from bp.updated_at) * 1000)::bigint
  into v_base_price, v_currency, v_base_price_version
  from catalog.product_base_price_profiles bp
  where bp.product_id = p_product_id
    and bp.tenant_id = p_tenant_id;

  if v_base_price is null then
    return query select
      p_product_id,
      v_unit_id,
      v_unit_name,
      0::numeric,
      coalesce(v_currency, 'VND'),
      null::numeric,
      null::numeric,
      null::uuid,
      null::text,
      v_base_price_version,
      false,
      'Cần có Giá cơ sở định giá trước';
    return;
  end if;

  select * into v_rule
  from catalog.store_price_rules r
  where r.tenant_id = p_tenant_id
  limit 1;

  if v_rule.id is null then
    return query select
      p_product_id,
      v_unit_id,
      v_unit_name,
      v_base_price,
      coalesce(v_currency, 'VND'),
      null::numeric,
      null::numeric,
      null::uuid,
      null::text,
      v_base_price_version,
      false,
      'Tenant chưa có Store Price Rule';
    return;
  end if;

  if v_rule.status <> 'active' then
    return query select
      p_product_id,
      v_unit_id,
      v_unit_name,
      v_base_price,
      coalesce(v_currency, 'VND'),
      null::numeric,
      null::numeric,
      v_rule.id,
      v_rule.name,
      v_base_price_version,
      false,
      'Store Price Rule đang không hoạt động';
    return;
  end if;

  select * into v_prices
  from catalog._compute_suggested_prices(
    v_base_price,
    v_rule.list_markup_ratio,
    v_rule.floor_markup_ratio
  );

  return query select
    p_product_id,
    v_unit_id,
    v_unit_name,
    v_base_price,
    coalesce(v_currency, 'VND'),
    v_prices.suggested_list_price,
    v_prices.suggested_floor_price,
    v_rule.id,
    v_rule.name,
    v_base_price_version,
    true,
    null::text;
end;
$$;

create or replace function catalog.apply_store_price_rule(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid default null,
  p_store_price_rule_id uuid default null,
  p_confirm_overwrite boolean default false,
  p_base_price_version bigint default null
)
returns table (
  product_id uuid,
  product_unit_id uuid,
  list_price numeric,
  floor_price numeric,
  store_price_rule_id uuid
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
  v_unit_id uuid;
  v_base_price numeric;
  v_base_price_version bigint;
  v_rule catalog.store_price_rules%rowtype;
  v_prices record;
  v_existing_list numeric;
  v_existing_floor numeric;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_pricing') then
    raise exception 'permission denied: catalog.product.manage_pricing';
  end if;

  if not exists (
    select 1 from catalog.products
    where id = p_product_id and tenant_id = p_tenant_id and deleted_at is null
  ) then
    raise exception 'product not found';
  end if;

  perform catalog._ensure_product_has_base_unit(p_tenant_id, p_product_id);

  v_unit_id := catalog._resolve_base_product_unit_id(p_tenant_id, p_product_id, p_product_unit_id);
  if v_unit_id is null then
    raise exception 'missing base unit';
  end if;

  select bp.base_price_amount,
         floor(extract(epoch from bp.updated_at) * 1000)::bigint
  into v_base_price, v_base_price_version
  from catalog.product_base_price_profiles bp
  where bp.product_id = p_product_id
    and bp.tenant_id = p_tenant_id;

  if v_base_price is null then
    raise exception 'missing_base_price';
  end if;

  if p_base_price_version is not null and p_base_price_version <> v_base_price_version then
    raise exception 'stale_base_price';
  end if;

  select * into v_rule
  from catalog.store_price_rules r
  where r.tenant_id = p_tenant_id
    and (p_store_price_rule_id is null or r.id = p_store_price_rule_id)
  limit 1;

  if v_rule.id is null then
    raise exception 'store_price_rule_not_found';
  end if;

  if v_rule.status <> 'active' then
    raise exception 'store_price_rule_inactive';
  end if;

  select pb.list_price_amount, pb.floor_price_amount
  into v_existing_list, v_existing_floor
  from catalog.product_unit_price_bands pb
  where pb.product_id = p_product_id
    and pb.product_unit_id = v_unit_id
  limit 1;

  if v_existing_list is not null and v_existing_floor is not null and not p_confirm_overwrite then
    raise exception 'price_band_overwrite_required';
  end if;

  select * into v_prices
  from catalog._compute_suggested_prices(
    v_base_price,
    v_rule.list_markup_ratio,
    v_rule.floor_markup_ratio
  );

  insert into catalog.product_unit_price_bands (
    tenant_id,
    product_id,
    product_unit_id,
    list_price_amount,
    floor_price_amount,
    store_price_rule_id,
    source_type,
    is_custom_override,
    updated_at
  )
  values (
    p_tenant_id,
    p_product_id,
    v_unit_id,
    v_prices.suggested_list_price,
    v_prices.suggested_floor_price,
    v_rule.id,
    'ruleBased',
    false,
    now()
  )
  on conflict on constraint uq_product_unit_price_bands_unit do update set
    list_price_amount = excluded.list_price_amount,
    floor_price_amount = excluded.floor_price_amount,
    store_price_rule_id = excluded.store_price_rule_id,
    source_type = excluded.source_type,
    is_custom_override = excluded.is_custom_override,
    updated_at = now();

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'apply_store_price_rule',
    jsonb_build_object(
      'product_unit_id', v_unit_id,
      'store_price_rule_id', v_rule.id,
      'list_price', v_prices.suggested_list_price,
      'floor_price', v_prices.suggested_floor_price,
      'previous_list_price', v_existing_list,
      'previous_floor_price', v_existing_floor
    ),
    v_actor_id
  );

  return query select
    p_product_id,
    v_unit_id,
    v_prices.suggested_list_price,
    v_prices.suggested_floor_price,
    v_rule.id;
end;
$$;

create or replace function catalog.get_product_control_center(
  p_tenant_id uuid,
  p_product_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.view_detail') then
    raise exception 'permission denied: catalog.product.view_detail';
  end if;

  select jsonb_build_object(
    'product_id', p.id,
    'name', p.name,
    'trade_name', p.trade_name,
    'sku', p.sku,
    'barcode', p.barcode,
    'description', p.description,
    'note', p.note,
    'business_status', p.business_status::text,
    'is_soft_deleted', (p.deleted_at is not null),
    'primary_image_url', (
      select i.file_url
      from catalog.product_images i
      where i.product_id = p.id and i.tenant_id = p_tenant_id
      order by i.is_primary desc, i.sort_order asc
      limit 1
    ),
    'images', coalesce((
      select jsonb_agg(i.file_url order by i.is_primary desc, i.sort_order asc)
      from catalog.product_images i
      where i.product_id = p.id and i.tenant_id = p_tenant_id and i.file_url is not null
    ), '[]'::jsonb),
    'base_unit_name', (
      select u.unit_name
      from catalog.product_units u
      where u.product_id = p.id and u.is_base_unit = true
      limit 1
    ),
    'conversion_units', coalesce((
      select jsonb_agg(jsonb_build_object(
        'name', u.unit_name,
        'conversion_rate', u.conversion_rate_to_base,
        'is_active', true
      ) order by u.created_at)
      from catalog.product_units u
      where u.product_id = p.id
        and u.tenant_id = p_tenant_id
        and u.is_base_unit = false
    ), '[]'::jsonb),
    'stock_mode', f.stock_mode,
    'stock_qty', (
      select sp.initial_stock
      from catalog.product_stock_profiles sp
      where sp.product_id = p.id
      limit 1
    ),
    'stock_version', (
      select sp.stock_version
      from catalog.product_stock_profiles sp
      where sp.product_id = p.id
      limit 1
    ),
    'base_price_mode', f.base_price_mode,
    'base_price_amount', (
      select bp.base_price_amount
      from catalog.product_base_price_profiles bp
      where bp.product_id = p.id
      limit 1
    ),
    'base_price_currency', coalesce((
      select bp.currency
      from catalog.product_base_price_profiles bp
      where bp.product_id = p.id
      limit 1
    ), 'VND'),
    'list_price', (
      select pb.list_price_amount
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu on bu.id = pb.product_unit_id and bu.is_base_unit = true
      where pb.product_id = p.id
      limit 1
    ),
    'floor_price', (
      select pb.floor_price_amount
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu on bu.id = pb.product_unit_id and bu.is_base_unit = true
      where pb.product_id = p.id
      limit 1
    ),
    'price_band_source_type', (
      select pb.source_type
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu on bu.id = pb.product_unit_id and bu.is_base_unit = true
      where pb.product_id = p.id
      limit 1
    ),
    'store_price_rule_name', (
      select sr.name
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu on bu.id = pb.product_unit_id and bu.is_base_unit = true
      left join catalog.store_price_rules sr on sr.id = pb.store_price_rule_id
      where pb.product_id = p.id
      limit 1
    ),
    'is_custom_override', coalesce((
      select pb.is_custom_override
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu on bu.id = pb.product_unit_id and bu.is_base_unit = true
      where pb.product_id = p.id
      limit 1
    ), false),
    'has_base_unit', f.has_base_unit,
    'has_images', f.has_images,
    'has_stock', f.has_stock,
    'has_base_price', f.has_base_price,
    'has_price_band', f.has_price_band,
    'has_required_custom_fields', f.has_required_custom_fields,
    'change_history_preview', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', h.id,
        'occurred_at', h.created_at,
        'actor_display_name', left(h.actor_id::text, 8),
        'change_type', h.action,
        'summary', h.action,
        'value_before', h.payload ->> 'value_before',
        'value_after', h.payload ->> 'value_after'
      ) order by h.created_at desc)
      from (
        select *
        from catalog.product_change_history h
        where h.product_id = p.id and h.tenant_id = p_tenant_id
        order by h.created_at desc
        limit 3
      ) h
    ), '[]'::jsonb)
  )
  into v_result
  from catalog.products p
  cross join lateral catalog._product_operational_facts(p_tenant_id, p.id) f
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
    and p.deleted_at is null;

  if v_result is null then
    raise exception 'product not found';
  end if;

  return v_result;
end;
$$;

